import sys
import json
import xml.etree.ElementTree as ET

def parse_xml_to_json(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        services = []

        for service in root.findall('service'):
            name = service.get('name')
            host = service.find('host').text
            port_text = service.find('port').text
            port = int(port_text)

            services.append({
                'name': name,
                'host': host,
                'port': port
            })

        return json.dumps(services)
    except (ET.ParseError, IOError) as e:
        print(f"Error: Failed to parse or read XML file: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python xml_summary.py <xml_file_path>", file=sys.stderr)
        sys.exit(1)

    xml_file = sys.argv[1]
    json_output = parse_xml_to_json(xml_file)
    print(json_output)
